<script setup>
import RecordPagination from "./ui/RecordPagination.vue"
import {usePagination} from "../usePagination.js"
import {computed,watch} from 'vue'
import {useLearning} from '../useLearning.js'
import {icon} from '../assets.js'
import {competitionArtwork as art} from '../competitionArtwork.js'
import TaskPanel from './TaskPanelV3.vue'
import TutorPanel from './TutorPanel.vue'
import AttemptHistory from './AttemptHistoryV3.vue'
import EvidenceCard from './EvidenceCard.vue'
const emit=defineEmits(['note','add-material'])
const {state,currentLesson,navigate,selectLesson,setLessonTab,loadTaskById}=useLearning()
const tabs=[['lecture','讲义'],['practice','练习'],['history','作答记录']]
const tasks=computed(()=>currentLesson.value?.tasks||[currentLesson.value?.practice,currentLesson.value?.review].filter(Boolean))
const names={reflection:'解释与自检',diagnostic:'先看看从哪里开始',practice:'轮到你试一试',review:'换题检查理解',remediation:'补上这一小步',bridge_demo:'换个学科再看一次'}
const next=computed(()=>state.next?.lesson_id===currentLesson.value?.id?state.next:null)
const lessonRowsSource=computed(()=>state.current?.lessons||[])
const {page:lessonPage,items:lessonRows}=usePagination(lessonRowsSource,()=>state.current?.id)
watch(()=>currentLesson.value?.id,id=>{const i=lessonRowsSource.value.findIndex(l=>l.id===id);lessonPage.value=Math.max(1,Math.floor(i/10)+1)},{immediate:true})
</script>
<template><main class="lesson-v3"><aside class="lesson-rail"><button class="back-link" @click="navigate('learning')">‹ 我的学习</button><span class="course-tag">{{ state.current.domain }}</span><h2>{{ state.current.title }}</h2><p>{{ state.current.daily_minutes }} 分钟 / 天</p><label class="compact-lesson-select">当前单元<select :value="currentLesson.id" @change="selectLesson($event.target.value)"><option v-for="lesson in state.current.lessons" :key="lesson.id" :value="lesson.id">{{ lesson.title }}</option></select></label><div class="lesson-steps"><button v-for="(lesson,index) in lessonRows" :key="lesson.id" :class="{selected:currentLesson.id===lesson.id}" @click="selectLesson(lesson.id)"><span>{{ String((lessonPage-1)*10+index+1).padStart(2,'0') }}</span><div><strong>{{ lesson.title }}</strong><small>{{ state.current.states[lesson.id]?.label||'尚未练习' }}</small></div></button><RecordPagination v-model="lessonPage" :total="lessonRowsSource.length" label="课程单元"/></div><button class="secondary-button" @click="navigate('graph')">查看目标关系</button><button class="text-button rail-material" @click="emit('add-material')">加入相关资料</button></aside>
<section class="lesson-study"><header class="study-lesson-heading"><img :src="art.lessonBanner||art.lessonScene" alt="书本与石桥"><div><span>当前单元 · {{ currentLesson.minutes }} 分钟</span><h1>{{ currentLesson.title }}</h1><p>{{ currentLesson.objective }}</p></div></header><div class="lesson-view-tabs" role="tablist" aria-label="单元内容"><button v-for="(item,index) in tabs" :key="item[0]" :id="'lesson-tab-'+item[0]" role="tab" :aria-selected="state.lessonTab===item[0]" :aria-controls="'lesson-pane-'+item[0]" :tabindex="state.lessonTab===item[0]?0:-1" @click="setLessonTab(item[0])" @keydown.right.prevent="setLessonTab(tabs[(index+1)%3][0],true)" @keydown.left.prevent="setLessonTab(tabs[(index+2)%3][0],true)">{{ item[1] }}</button></div><EvidenceCard/>
<section v-if="state.lessonTab==='lecture'" id="lesson-pane-lecture" class="study-panel" role="tabpanel" aria-labelledby="lesson-tab-lecture"><section v-for="(section,index) in currentLesson.sections" :key="section.title" class="lesson-section"><span class="section-index">{{ index+1 }}</span><div><h2>{{ section.title }}</h2><p>{{ section.text }}</p></div></section><section v-if="currentLesson.reference" class="lesson-curriculum-reference"><strong>课程依据：{{ currentLesson.reference.title }}</strong><p>{{ currentLesson.reference.usage }}</p><a :href="currentLesson.reference.url" target="_blank" rel="noopener noreferrer">查看来源</a><p v-if="currentLesson.prerequisites?.length">建议先学：{{ currentLesson.prerequisites.map(id=>state.current.lessons.find(l=>l.id===id)?.title||id).join('、') }}</p></section><p class="source-caption">{{ currentLesson.source_label }}</p><div class="task-actions"><button class="secondary-button" @click="emit('note')">记下自己的理解</button><button class="primary-button" @click="setLessonTab('practice')">去试一试</button><button v-if="currentLesson.course_id==='programming'&&currentLesson.chapter>=4" class="secondary-button" @click="navigate('pbl')">进入按主题汇总项目</button></div></section>
<section v-else-if="state.lessonTab==='history'" id="lesson-pane-history" class="study-panel" role="tabpanel" aria-labelledby="lesson-tab-history"><h2>本单元的实际作答</h2><p class="section-description">每次结论都保留当时的题目、作答和帮助条件。</p><AttemptHistory expanded/><button class="secondary-button" @click="setLessonTab('practice')">回到练习</button></section>
<section v-else id="lesson-pane-practice" role="tabpanel" aria-labelledby="lesson-tab-practice"><label class="task-picker">当前任务<select :value="state.run?.task?.id||''" :disabled="!!state.taskBusyId||state.taskBusy||state.evidenceBusy" @change="loadTaskById($event.target.value)"><option value="" disabled>选择一项任务</option><option v-for="task in tasks" :key="task.id" :value="task.id">{{ names[task.purpose]||names[task.id===currentLesson.review?.id?'review':'practice'] }}</option></select></label><TaskPanel/></section></section>
<aside class="lesson-tutor-column"><TutorPanel @add-material="emit('add-material')"/><div v-if="next" class="lesson-next-strip"><img :src="icon('flag')" alt=""><div><strong>当前建议：{{ next.title }}</strong><p>{{ next.reason }}</p></div></div></aside></main></template>
